    if mibBuilder.loadTexts: ciscoC2900MIB.setRevisionsDescriptions(('Added the c2900PortAddrSecureAgingTime,\n             c2900PortAddrSecureAgingType and \n             c2900PortAddrSecureAgingStatic\n             MIB objects to port entry and port group;\n             Also added c2900NotificationsGroup and \n             c2900PortStatsGroupRev1 object.', 'Added the c2900PortVoiceVlanId\n             MIB object to port group.', 'Modified the description for the c2900InfoSelfTestFailed object\n             so that the bits of the self-test bit array are explained.', 'Modified the description for the c2900InfoSelfTestFailed object\n             so that the bits of the self-test bit array are explained.', 'Added enumerated values to c2900ModuleType for:\n                ATM modules\n                VLAN-trunking 10/100 Ethernet modules\n                Gigabit Ethernet module\n\n             Added one enumerated value to c2900PortAdminSpeed\n             to describe ATM 155.52 Mbps speed.', 'Added the c2900PortSpantreeFast MIB object to port group.', 'Added the c2900PortNoMonitorDestinationPort MIB object\n             to remove a port from the monitored list.\n\n             Added c2900Portdot1dBasePort to C2900PortEntry.\n\n             Removed enumerated value securityDynamic(3) from the\n             MIB object c2900PortUsageApplication',))
